import Foundation

/// An airport with scheduled passenger service.
///
/// Listed airports come from the bundled directory, generated by
/// `Scripts/generate_airports.py`. An unlisted airport carries only the code
/// a person typed, so it has no city or time zone.
struct Airport: Codable, Hashable, Identifiable, Sendable {
    /// The three-letter IATA code, such as `YVR`.
    let code: String
    let name: String
    let city: String
    /// The city an airport serves when it sits outside it, such as London for Luton.
    var metro: String?
    /// The ISO 3166-1 region code, such as `CA`.
    let country: String
    /// The IANA identifier the departure time is entered in.
    var timeZone: String?
    /// 0 for a major hub through 2 for a regional airport.
    var size: Int = 2
    /// Other names and codes people search with, never shown.
    var aliases: String?

    var id: String { code }

    /// The city travellers name when they talk about this airport.
    var servedCity: String { metro ?? city }

    var countryName: String {
        Locale.current.localizedString(forRegionCode: country) ?? country
    }

    var isListed: Bool { timeZone != nil }

    static func unlisted(code: String) -> Self {
        Airport(code: code, name: code, city: "", country: "")
    }

    /// Whether `value` reads as an IATA airport code: three Latin letters.
    static func isCode(_ value: String) -> Bool {
        value.wholeMatch(of: /[A-Z]{3}/) != nil
    }
}
